import{_ as a,o as r,c as e,a2 as o}from"./chunks/framework.BZO4qERu.js";const d=JSON.parse('{"title":"リファレンス","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guides/index.md","filePath":"ja/guides/index.md","lastUpdated":1792323081000}'),s={name:"ja/guides/index.md"};function l(n,t,i,h,g,m){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="リファレンス" tabindex="-1">リファレンス <a class="header-anchor" href="#リファレンス" aria-label="Permalink to &quot;リファレンス&quot;">​</a></h1><p>Memoh リファレンスへようこそ。Memoh のインストール・設定・活用に必要な情報はすべてここにあり、3 つのセクションで構成されています。</p><h2 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h2><p>Memoh が初めてなら、ここから始めましょう。アプリのインストール、最初の Bot の作成、チャネルへの接続、そして日常的な基本操作を学べます。</p><ul><li><strong><a href="./overview.html">概要</a></strong>：Memoh とは何か、各パーツがどう組み合わさっているか。</li><li><strong><a href="./quick-start.html">クイックスタート</a></strong>：アプリをインストールしてサインインし、最初の Bot を作成して実際の仕事を任せ、チャットプラットフォームに接続します。</li><li><strong><a href="./working-with-bots.html">Bot との協働</a></strong>：どんなタスクを任せるか、依頼をどう伝えるか、いつ Bot を分けるか。さらにタブごとの設定リファレンスも。</li><li><strong><a href="./sessions.html">セッション</a></strong>：chat と discuss、ルーティング、ステータスパネルを理解します。</li><li><strong><a href="./files.html">ファイル</a></strong>：Bot のワークスペースにあるファイルを閲覧・編集します。</li><li><strong><a href="./slash-commands.html">スラッシュコマンド</a></strong>：コマンドで日常の操作を手早く済ませます。</li><li><strong><a href="./../integrations/channels/">チャネル</a></strong>：Memoh を Slack、Telegram、Feishu、Discord などのプラットフォームに接続します。</li></ul><h2 id="高度な機能" tabindex="-1">高度な機能 <a class="header-anchor" href="#高度な機能" aria-label="Permalink to &quot;高度な機能&quot;">​</a></h2><p>基礎が固まったら、さらに深く使いこなしましょう。これらのページでは、高度な機能、自動化、外部プロバイダーを扱います。</p><ul><li><strong><a href="./extensions.html">拡張機能の選び方</a></strong>：スキル、Hooks、MCP、コネクター、マーケットプレイスのどれを使うべきか。</li><li><strong><a href="./acp.html">Agents / ACP</a></strong>：マルチエージェントワークフローを構築し、Agent Client Protocol と連携します。</li><li><strong><a href="./approvals.html">承認と信頼</a></strong>：Bot が何に触れられるか、いつあなたに確認するか、どの操作を承認の後ろに残すか。</li><li><strong><a href="./access.html">アクセス制御</a></strong>：ACL プリセット、アクセスモード、スコープ付きルールを設定します。</li><li><strong><a href="./container.html">ワークスペース</a></strong>：プロダクト UI からワークスペースの挙動を理解します。</li><li><strong><a href="./browser-computer-use.html">Browser / Computer Use</a></strong>：ヘッド付きブラウザと可視デスクトップのセッションを使います。</li><li><strong><a href="./skills.html">スキル</a></strong> と <strong><a href="./supermarket.html">マーケットプレイス</a></strong>：再利用できるプロンプトモジュールやテンプレートを追加します。</li><li><strong><a href="./../self-hosted/connectors.html">コネクター</a></strong>：GitHub や Notion などのサードパーティサービスに接続します。</li><li><strong><a href="./hooks.html">Hooks</a></strong> と <strong><a href="./mcp.html">MCP</a></strong>：ツール、自動化ルール、外部データソースをつなぎます。</li><li><strong><a href="./memory.html">長期メモリ</a></strong>：メモリプロバイダーを設定したうえで長期メモリを管理します。</li><li><strong><a href="./compaction.html">コンテキスト圧縮</a></strong>：現在のセッションのコンテキスト使用量を減らします。</li><li><strong><a href="./schedule.html">スケジュールタスク</a></strong>：cron スケジュールで定期的な仕事を実行します。</li><li><strong><a href="./../integrations/providers/llm.html">モデルプロバイダー</a></strong>：モデルプロバイダーとモデル。ウェブ検索・動画・メモリ・TTS の各プロバイダーはサイドバーの同じ階層にあります。</li></ul><h2 id="ユースケース" tabindex="-1">ユースケース <a class="header-anchor" href="#ユースケース" aria-label="Permalink to &quot;ユースケース&quot;">​</a></h2><h2 id="ヘルプの入手" tabindex="-1">ヘルプの入手 <a class="header-anchor" href="#ヘルプの入手" aria-label="Permalink to &quot;ヘルプの入手&quot;">​</a></h2><p>本サイトはプロダクトのリファレンスドキュメントです。サブスクリプションプラン、credits の課金、アカウントに関する質問、そして Memoh チームへの連絡方法については、<a href="https://memoh.ai/help" target="_blank" rel="noreferrer">ヘルプセンター</a> をご覧ください。</p>',11)])])}const f=a(s,[["render",l]]);export{d as __pageData,f as default};
